package com.optarena;

public class Grades {
    // Map a score to a letter: <60 F, <70 D, <80 C, <90 B, else A.
    public String classify(int score) {
        if (score < 60) {
            return "F";
        }
        if (score < 70) {
            return "D";
        }
        if (score < 80) {
            return "C";
        }
        if (score < 90) {
            return "B";
        }
        return "A";
    }
}

