package com.optarena;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class GradesTest {

    private final Grades grades = new Grades();

    @Test
    void lowScoresAreF() {
        assertEquals("F", grades.classify(0));
        assertEquals("F", grades.classify(59));
    }

    @Test
    void boundaries() {
        assertEquals("D", grades.classify(60));
        assertEquals("C", grades.classify(75));
        assertEquals("C", grades.classify(79));
        assertEquals("B", grades.classify(89));
    }

    @Test
    void highScoresAreA() {
        assertEquals("A", grades.classify(90));
        assertEquals("A", grades.classify(100));
    }
}

